'use client';
/**
 * The feed's signature: a registration field. Every coral plate (Prints.tsx, and the profile name's coral copy)
 * registers here. One rAF loop turns how fast the pointer and the page are moving into a misregistration of
 * 1–4 px — the coral plate lags behind the motion like paper slipping on the drum — and each plate follows that
 * target on a spring. The sheet under the pointer (hovered, pressed or holding focus) snaps into exact register on
 * the quick `press` spring. When nothing moves the plates settle to a hair (0.75 px) out, the riso look at rest,
 * and the loop goes to sleep.
 *
 * Transform only (compositor), one style write per plate per frame, no React renders while it runs.
 * Reduced motion: the loop never starts and every plate sits exactly in register.
 */
import { createContext, useCallback, useContext, useEffect, useRef, useState, type RefObject } from 'react';
import { spring, stepSpring, useRafLoop, useStudioMotion, type SpringConfig } from '../../../motion';

export type Register = (el: HTMLElement | SVGElement) => () => void;
export const RegistrationContext = createContext<Register | null>(null);

/** Join the field: the element becomes a coral plate that drifts and snaps back into register. */
export function usePlate(ref: RefObject<HTMLElement | SVGElement | null>): void {
  const register = useContext(RegistrationContext);
  useEffect(() => {
    const el = ref.current;
    if (!el || !register) return;
    return register(el);
  }, [register, ref]);
}

interface Plate { el: HTMLElement | SVGElement; sheet: Element | null; x: number; y: number; vx: number; vy: number }

const REST = 0.75; // px out of register when still
const MIN = 1; // px as soon as something moves
const MAX = 4; // px at a fast flick or scroll
const DEAD = 40; // px/s of motion that still counts as still
const FULL = 1400; // px/s that reaches MAX

const step = (p: Plate, gx: number, gy: number, s: SpringConfig, dt: number) => {
  const ax = { x: p.x, v: p.vx }, ay = { x: p.y, v: p.vy };
  stepSpring(ax, gx, s, dt); stepSpring(ay, gy, s, dt);
  p.x = ax.x; p.vx = ax.v; p.y = ay.x; p.vy = ay.v;
};

export function useRegistrationField(root: RefObject<HTMLElement | null>): Register {
  const { reduced } = useStudioMotion();
  const plates = useRef(new Set<Plate>());
  const engaged = useRef<{ hover: Element | null; press: Element | null; focus: Element | null }>({ hover: null, press: null, focus: null });
  const m = useRef({ px: 0, py: 0, pt: 0, vx: 0, vy: 0, sy: 0, st: 0, svy: 0, dx: 0.8, dy: 0.6 });
  const awakeRef = useRef(false);
  const [awake, setAwake] = useState(false);
  const wake = useCallback(() => {
    if (awakeRef.current) return;
    awakeRef.current = true;
    setAwake(true);
  }, []);

  const register = useCallback<Register>((el) => {
    const p: Plate = { el, sheet: el.closest('[data-sheet]'), x: 0, y: 0, vx: 0, vy: 0 };
    plates.current.add(p);
    el.style.transform = '';
    wake();
    return () => { plates.current.delete(p); el.style.transform = ''; };
  }, [wake]);

  // Inputs: pointer speed anywhere on the page, scroll speed of the page, and which sheet is being handled.
  useEffect(() => {
    const el = root.current;
    if (!el || reduced) return;
    const s = m.current;
    const onMove = (e: PointerEvent) => {
      const t = e.timeStamp;
      const dt = (t - s.pt) / 1000;
      if (s.pt && dt > 0.004 && dt < 0.2) {
        const k = 0.35;
        s.vx += (((e.clientX - s.px) / dt) - s.vx) * k;
        s.vy += (((e.clientY - s.py) / dt) - s.vy) * k;
      }
      s.px = e.clientX; s.py = e.clientY; s.pt = t;
      wake();
    };
    const onScroll = () => {
      const t = performance.now();
      const y = window.scrollY;
      const dt = (t - s.st) / 1000;
      if (s.st && dt > 0.004 && dt < 0.2) s.svy += (((y - s.sy) / dt) - s.svy) * 0.4;
      s.sy = y; s.st = t;
      wake();
    };
    const sheetOf = (t: EventTarget | null) => (t instanceof Element ? t.closest('[data-sheet]') : null);
    const onOver = (e: PointerEvent) => { if (e.pointerType === 'mouse') { engaged.current.hover = sheetOf(e.target); wake(); } };
    const onLeave = () => { engaged.current.hover = null; wake(); };
    const onDown = (e: PointerEvent) => { engaged.current.press = sheetOf(e.target); wake(); };
    const onUp = () => { if (engaged.current.press) { engaged.current.press = null; wake(); } };
    const onFocusIn = (e: FocusEvent) => { engaged.current.focus = sheetOf(e.target); wake(); };
    const onFocusOut = (e: FocusEvent) => { if (!el.contains(e.relatedTarget as Node | null)) { engaged.current.focus = null; wake(); } };
    window.addEventListener('pointermove', onMove, { passive: true });
    window.addEventListener('scroll', onScroll, { passive: true });
    el.addEventListener('pointerover', onOver);
    el.addEventListener('pointerleave', onLeave);
    el.addEventListener('pointerdown', onDown);
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onUp);
    el.addEventListener('focusin', onFocusIn);
    el.addEventListener('focusout', onFocusOut);
    return () => {
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('scroll', onScroll);
      el.removeEventListener('pointerover', onOver);
      el.removeEventListener('pointerleave', onLeave);
      el.removeEventListener('pointerdown', onDown);
      window.removeEventListener('pointerup', onUp);
      window.removeEventListener('pointercancel', onUp);
      el.removeEventListener('focusin', onFocusIn);
      el.removeEventListener('focusout', onFocusOut);
    };
  }, [root, reduced, wake]);

  // Reduced motion: everything in register, nothing running.
  useEffect(() => {
    if (!reduced) return;
    for (const p of plates.current) { p.x = p.y = p.vx = p.vy = 0; p.el.style.transform = ''; }
    awakeRef.current = false;
    setAwake(false);
  }, [reduced]);

  useRafLoop(root, (dt) => {
    const s = m.current;
    // Speeds fade on their own once input stops (≈ 200 ms), so the drift relaxes without new events.
    s.vx *= Math.exp(-dt * 6);
    s.vy *= Math.exp(-dt * 6);
    s.svy *= Math.exp(-dt * 5);
    // Scrolling down moves the content up the screen, so the page's own motion is -scroll velocity.
    const vx = s.vx, vy = s.vy - s.svy * 0.8;
    const speed = Math.hypot(vx, vy);
    if (speed > DEAD) { s.dx = -vx / speed; s.dy = -vy / speed; }
    const mag = speed <= DEAD ? REST : Math.min(MAX, MIN + ((speed - DEAD) / (FULL - DEAD)) * (MAX - MIN));
    const tx = s.dx * mag, ty = s.dy * mag;
    const { hover, press, focus } = engaged.current;
    let busy = speed > DEAD * 0.25;
    for (const p of plates.current) {
      const on = !!p.sheet && (p.sheet === hover || p.sheet === press || p.sheet === focus);
      const gx = on ? 0 : tx, gy = on ? 0 : ty;
      step(p, gx, gy, on ? spring.press : spring.settle, dt);
      if (Math.abs(p.x - gx) > 0.02 || Math.abs(p.y - gy) > 0.02 || Math.abs(p.vx) > 0.05 || Math.abs(p.vy) > 0.05) busy = true;
      p.el.style.transform = `translate3d(${p.x.toFixed(2)}px, ${p.y.toFixed(2)}px, 0)`;
    }
    if (!busy) { awakeRef.current = false; setAwake(false); }
  }, awake && !reduced);

  return register;
}

'use client';
/**
 * A modal sheet contained in the demo (no top layer, no position: fixed): a layer covers the demo and the panel
 * is `position: sticky`, so it sits at the bottom of the viewport on phones and as a right-hand drawer below the
 * gallery bar on wide containers. The caller makes the page behind it `inert`; the sheet moves focus in, keeps Tab
 * inside it, closes on Esc or the scrim, and gives focus back to the control that opened it.
 *
 * Drag to dismiss: the head (with its grabber) follows the pointer along the sheet's own axis — down for the bottom
 * sheet, right for the drawer — with rubber-band resistance the other way, and the scrim fades with the distance.
 * Release past 30 % of the sheet or faster than 0.5 px/ms closes it at the speed of the throw; anything less springs
 * back on the `settle` spring. The Close button, Esc and the scrim do the same without a gesture.
 */
import { useCallback, useEffect, useId, useRef, type KeyboardEvent, type PointerEvent, type ReactNode, type RefObject } from 'react';
import { duration as D, easing, spring, springToLinear, useStudioMotion } from '../../../motion';
import styles from './styles.module.css';

const SETTLE = springToLinear(spring.settle);
const FOCUSABLE = 'button:not([disabled]), a[href], textarea:not([disabled]), input:not([disabled]), [tabindex="0"]';
const ease = (b: readonly number[]) => `cubic-bezier(${b.join(', ')})`;

interface Drag { id: number; x: number; y: number; axis: 'x' | 'y'; size: number; offset: number; samples: { d: number; t: number }[] }

export function Sheet({ title, kicker, onClose, children, footer, returnTo }: {
  /** The control that opened the sheet (captured before the page became inert); focus returns to it on close. */
  returnTo: RefObject<HTMLElement | null>;
  title: string;
  kicker?: string;
  onClose: () => void;
  children: ReactNode;
  footer?: ReactNode;
}) {
  const { reduced } = useStudioMotion();
  const panel = useRef<HTMLDivElement>(null);
  const scrim = useRef<HTMLDivElement>(null);
  const closing = useRef(false);
  const anim = useRef<Animation | null>(null);
  const drag = useRef<Drag | null>(null);
  const titleId = useId();

  useEffect(() => {
    const el = panel.current;
    closing.current = false;
    el?.focus({ preventScroll: true });
    if (el && typeof el.animate === 'function') {
      const axis = getComputedStyle(el).getPropertyValue('--sheet-axis').trim() === 'x' ? 'X' : 'Y';
      anim.current = reduced
        ? el.animate([{ opacity: 0 }, { opacity: 1 }], { duration: D.fast, easing: 'linear' })
        : el.animate([{ transform: `translate${axis}(48px)`, opacity: 0 }, { transform: 'none', opacity: 1 }], { duration: SETTLE.duration, easing: SETTLE.easing });
    }
    return () => {
      anim.current?.cancel();
      anim.current = null;
      const opener = returnTo.current;
      if (opener?.isConnected) opener.focus({ preventScroll: true });
    };
  }, [reduced, returnTo]);

  /** Close from wherever the panel is now (mid-drag included); a throw keeps its speed. */
  const close = useCallback((velocity = 0) => {
    const el = panel.current;
    if (closing.current) return;
    closing.current = true;
    if (!el || typeof el.animate !== 'function') { onClose(); return; }
    const axis = getComputedStyle(el).getPropertyValue('--sheet-axis').trim() === 'x' ? 'x' : 'y';
    const size = axis === 'y' ? el.offsetHeight : el.offsetWidth;
    const from = el.style.transform || 'none';
    const at = drag.current?.offset ?? 0;
    el.style.transform = '';
    anim.current?.cancel();
    const fade = scrim.current;
    if (reduced) {
      anim.current = el.animate([{ transform: from, opacity: 1 }, { transform: from, opacity: 0 }], { duration: D.fast, easing: 'linear', fill: 'forwards' });
    } else {
      // Keep the throw's speed: the remaining distance at the release velocity, clamped to the token range.
      const rest = Math.max(0, size - at);
      const ms = velocity > 0.2 ? Math.max(D.fast, Math.min(D.moderate, rest / velocity)) : D.base;
      anim.current = el.animate([{ transform: from }, { transform: `translate${axis.toUpperCase()}(${size + 24}px)` }], { duration: ms, easing: velocity > 0.2 ? ease(easing.standard) : ease(easing.exit), fill: 'forwards' });
      if (fade) fade.animate([{ opacity: fade.style.opacity || '1' }, { opacity: 0 }], { duration: ms, easing: 'linear', fill: 'forwards' });
    }
    anim.current.finished.then(onClose, () => {});
  }, [onClose, reduced]);

  // Esc also works if focus has left the sheet (e.g. a control inside it was removed).
  useEffect(() => {
    const onDocKey = (e: globalThis.KeyboardEvent) => { if (e.key === 'Escape' && !e.defaultPrevented) close(); };
    document.addEventListener('keydown', onDocKey);
    return () => document.removeEventListener('keydown', onDocKey);
  }, [close]);

  const onKey = (e: KeyboardEvent) => {
    if (e.key === 'Escape') { e.preventDefault(); close(); return; }
    if (e.key !== 'Tab' || !panel.current) return;
    // Keep Tab inside the sheet: wrap from the last control to the first and back.
    const items = Array.from(panel.current.querySelectorAll<HTMLElement>(FOCUSABLE));
    if (!items.length) return;
    const first = items[0], last = items[items.length - 1], at = document.activeElement;
    if (e.shiftKey && (at === first || at === panel.current)) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && at === last) { e.preventDefault(); first.focus(); }
  };

  // ── drag to dismiss ──
  const onHeadDown = (e: PointerEvent<HTMLDivElement>) => {
    const el = panel.current;
    if (!el || closing.current || e.button !== 0 || (e.target as Element).closest('button, a, input, textarea')) return;
    const axis = getComputedStyle(el).getPropertyValue('--sheet-axis').trim() === 'x' ? 'x' : 'y';
    anim.current?.cancel();
    drag.current = { id: e.pointerId, x: e.clientX, y: e.clientY, axis, size: axis === 'y' ? el.offsetHeight : el.offsetWidth, offset: 0, samples: [{ d: 0, t: e.timeStamp }] };
    e.currentTarget.setPointerCapture?.(e.pointerId);
    el.dataset.dragging = '';
  };
  const onHeadMove = (e: PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    const el = panel.current;
    if (!d || d.id !== e.pointerId || !el) return;
    const raw = d.axis === 'y' ? e.clientY - d.y : e.clientX - d.x;
    // Free travel towards dismissal; the other way resists more the further it goes.
    const offset = raw >= 0 ? raw : -Math.sqrt(-raw) * 3;
    d.offset = offset;
    d.samples.push({ d: raw, t: e.timeStamp });
    if (d.samples.length > 6) d.samples.shift();
    el.style.transform = d.axis === 'y' ? `translateY(${offset}px)` : `translateX(${offset}px)`;
    if (scrim.current) scrim.current.style.opacity = String(Math.max(0, Math.min(1, 1 - Math.max(0, offset) / d.size)));
  };
  const onHeadUp = (e: PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    const el = panel.current;
    if (!d || d.id !== e.pointerId || !el) return;
    delete el.dataset.dragging;
    const a = d.samples[0], b = d.samples[d.samples.length - 1];
    const v = b.t > a.t ? (b.d - a.d) / (b.t - a.t) : 0; // px/ms, + = towards dismissal
    if (d.offset > d.size * 0.3 || (v > 0.5 && d.offset > 8)) { close(v); drag.current = null; return; }
    drag.current = null;
    const from = el.style.transform || 'none';
    el.style.transform = '';
    if (scrim.current) {
      const s = scrim.current;
      const o = s.style.opacity || '1';
      s.style.opacity = '';
      if (!reduced) s.animate([{ opacity: o }, { opacity: 1 }], { duration: SETTLE.duration, easing: SETTLE.easing });
    }
    if (!reduced && from !== 'none') anim.current = el.animate([{ transform: from }, { transform: 'none' }], { duration: SETTLE.duration, easing: SETTLE.easing });
  };

  return (
    <div className={styles.sheetLayer} onKeyDown={onKey}>
      <div ref={scrim} className={styles.sheetScrim} onClick={() => close()} aria-hidden="true" />
      <div ref={panel} role="dialog" aria-modal="true" aria-labelledby={titleId} tabIndex={-1} className={styles.sheetPanel}>
        <div className={styles.sheetHead} onPointerDown={onHeadDown} onPointerMove={onHeadMove} onPointerUp={onHeadUp} onPointerCancel={onHeadUp}>
          <span className={styles.grabber} aria-hidden="true" />
          <div>
            {kicker ? <p className={`mk-label ${styles.muted}`}>{kicker}</p> : null}
            <h2 id={titleId} className={styles.sheetTitle}>{title}</h2>
          </div>
          <button type="button" className={styles.iconBtn} onClick={() => close()}>
            <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M6 6l12 12M18 6 6 18" /></svg>
            <span className="mk-sr-only">Close</span>
          </button>
        </div>
        <div className={styles.sheetBody}>{children}</div>
        {footer ? <div className={styles.sheetFoot}>{footer}</div> : null}
      </div>
    </div>
  );
}

/**
 * Optimistic participation store + a simulated server (no network: setTimeout latency, in-memory state).
 *
 *  - Toggles flip the visible state in the same frame; requests carry the FINAL intended state (not "toggle"), are
 *    debounced so rapid taps send one request, and carry an idempotency key so a retried request cannot double-count.
 *  - Success reconciles counts with the server's value; failure rolls back to the last confirmed state and records a
 *    reason that the UI shows next to the control and announces politely.
 *  - "Simulate failed requests" makes every request fail, so rollback can be seen on purpose.
 */
import { PROFILE, POSTS, type CommentData } from './data';

export type CommentState = CommentData & { state: 'sent' | 'sending' | 'failed'; mine?: boolean };
export type ToggleKind = 'liked' | 'saved';
export interface PostState { liked: boolean; saved: boolean; likes: number; error: { kind: ToggleKind; message: string } | null; comments: CommentState[] }
export interface FeedState {
  posts: Record<string, PostState>;
  following: boolean;
  followers: number;
  followError: string | null;
  drafts: Record<string, string>;
  fail: boolean;
  announce: { n: number; text: string };
}

const LATENCY = 650;
const DEBOUNCE = 320;
const titleOf = (id: string) => POSTS.find((p) => p.id === id)?.title ?? 'this post';

export function createFeedStore() {
  let state: FeedState = {
    posts: Object.fromEntries(POSTS.map((p) => [p.id, { liked: false, saved: false, likes: p.likes, error: null, comments: p.comments.map((c) => ({ ...c, state: 'sent' as const })) }])),
    following: false, followers: PROFILE.followers, followError: null, drafts: {}, fail: false, announce: { n: 0, text: '' },
  };
  const listeners = new Set<() => void>();
  const set = (fn: (s: FeedState) => FeedState) => { state = fn(state); listeners.forEach((l) => l()); };
  const patchPost = (id: string, patch: Partial<PostState>) => set((s) => ({ ...s, posts: { ...s.posts, [id]: { ...s.posts[id], ...patch } } }));
  const say = (text: string) => set((s) => ({ ...s, announce: { n: s.announce.n + 1, text } }));

  // ── simulated server ──
  const server = {
    liked: Object.fromEntries(POSTS.map((p) => [p.id, false])) as Record<string, boolean>,
    saved: Object.fromEntries(POSTS.map((p) => [p.id, false])) as Record<string, boolean>,
    likes: Object.fromEntries(POSTS.map((p) => [p.id, p.likes])) as Record<string, number>,
    following: false, followers: PROFILE.followers as number,
    seen: new Map<string, unknown>(),
  };
  const timers = new Set<ReturnType<typeof setTimeout>>();
  let alive = true;
  const later = (fn: () => void, ms: number) => { const t = setTimeout(() => { timers.delete(t); if (alive) fn(); }, ms); timers.add(t); return t; };
  /** One request: resolves after LATENCY with `apply()`'s result; the same key always returns the first result. */
  const request = <T,>(key: string, apply: () => T): Promise<T> => {
    const willFail = state.fail;
    return new Promise<T>((resolve, reject) => {
      later(() => {
        if (willFail) { reject(new Error('offline')); return; }
        if (!server.seen.has(key)) server.seen.set(key, apply());
        resolve(server.seen.get(key) as T);
      }, LATENCY + Math.round(Math.random() * 200));
    });
  };

  // ── optimistic toggles (like / save) ──
  const confirmed: Record<string, boolean> = {};
  const confirmedLikes: Record<string, number> = Object.fromEntries(POSTS.map((p) => [p.id, p.likes]));
  const debounce = new Map<string, ReturnType<typeof setTimeout>>();
  const seq: Record<string, number> = {};
  let keyN = 0;

  const commit = (id: string, kind: ToggleKind) => {
    const k = `${id}:${kind}`;
    debounce.delete(k);
    const want = state.posts[id][kind];
    if (want === (confirmed[k] ?? false)) return;
    const n = (seq[k] = (seq[k] ?? 0) + 1);
    const key = `${k}:${want}:${++keyN}`;
    request(key, () => {
      if (server[kind][id] !== want) { server[kind][id] = want; if (kind === 'liked') server.likes[id] += want ? 1 : -1; }
      return { value: want, likes: server.likes[id] };
    }).then((res) => {
      confirmed[k] = res.value;
      if (kind === 'liked') confirmedLikes[id] = res.likes;
      if (seq[k] !== n) return;
      const p = state.posts[id];
      // Reconcile with the server's count unless the person has already changed their mind again.
      if (kind === 'liked' && p.liked === res.value) patchPost(id, { likes: res.likes });
    }, () => {
      if (seq[k] !== n || debounce.has(k)) return; // a newer intent is queued; it will be sent instead
      const message = kind === 'liked'
        ? `Couldn’t ${want ? 'like' : 'unlike'} “${titleOf(id)}”. Your change was undone — try again.`
        : `Couldn’t ${want ? 'save' : 'unsave'} “${titleOf(id)}”. Your change was undone — try again.`;
      patchPost(id, kind === 'liked'
        ? { liked: confirmed[k] ?? false, likes: confirmedLikes[id], error: { kind, message } }
        : { saved: confirmed[k] ?? false, error: { kind, message } });
      say(message);
    });
  };

  const toggle = (id: string, kind: ToggleKind) => {
    const p = state.posts[id];
    const next = !p[kind];
    patchPost(id, kind === 'liked' ? { liked: next, likes: p.likes + (next ? 1 : -1), error: null } : { saved: next, error: null });
    const k = `${id}:${kind}`;
    const t = debounce.get(k);
    if (t) { clearTimeout(t); timers.delete(t); }
    debounce.set(k, later(() => commit(id, kind), DEBOUNCE));
  };

  // ── follow ──
  let followSeq = 0;
  let followConfirmed = { following: false, followers: PROFILE.followers as number };
  let followTimer: ReturnType<typeof setTimeout> | null = null;
  const commitFollow = () => {
    followTimer = null;
    const want = state.following;
    if (want === followConfirmed.following) return;
    const n = ++followSeq;
    request(`follow:${want}:${++keyN}`, () => {
      if (server.following !== want) { server.following = want; server.followers += want ? 1 : -1; }
      return { following: server.following, followers: server.followers };
    }).then((res) => {
      followConfirmed = res;
      if (n === followSeq && state.following === res.following) set((s) => ({ ...s, followers: res.followers }));
    }, () => {
      if (n !== followSeq || followTimer) return;
      const message = `Couldn’t ${want ? 'follow' : 'unfollow'} ${PROFILE.name}. Your change was undone — try again.`;
      set((s) => ({ ...s, following: followConfirmed.following, followers: followConfirmed.followers, followError: message }));
      say(message);
    });
  };

  // ── comments ──
  let localN = 0;
  const sendComment = (postId: string, cid: string) => {
    request(`comment:${cid}:${++keyN}`, () => true).then(() => {
      updateComment(postId, cid, { state: 'sent' });
      say('Comment posted.');
    }, () => {
      updateComment(postId, cid, { state: 'failed' });
      say('Couldn’t post your comment. It is kept in the list with a Retry button.');
    });
  };
  const updateComment = (postId: string, cid: string, patch: Partial<CommentState>) => {
    const p = state.posts[postId];
    patchPost(postId, { comments: p.comments.map((c) => (c.id === cid ? { ...c, ...patch } : c)) });
  };

  return {
    get: () => state,
    subscribe: (l: () => void) => { listeners.add(l); return () => { listeners.delete(l); }; },
    revive: () => { alive = true; },
    dispose: () => { alive = false; timers.forEach(clearTimeout); timers.clear(); debounce.clear(); },
    toggle,
    likeOnce: (id: string) => { if (!state.posts[id].liked) toggle(id, 'liked'); },
    clearError: (id: string) => patchPost(id, { error: null }),
    toggleFollow: () => {
      set((s) => ({ ...s, following: !s.following, followers: s.followers + (s.following ? -1 : 1), followError: null }));
      if (followTimer) { clearTimeout(followTimer); timers.delete(followTimer); }
      followTimer = later(commitFollow, DEBOUNCE);
    },
    setFail: (fail: boolean) => set((s) => ({ ...s, fail })),
    setDraft: (id: string, text: string) => set((s) => ({ ...s, drafts: { ...s.drafts, [id]: text } })),
    postComment: (postId: string, text: string) => {
      const cid = `mine-${++localN}`;
      const comment: CommentState = { id: cid, author: 'You', initials: 'YOU', iso: new Date().toISOString(), ago: 'now', text, state: 'sending', mine: true };
      set((s) => ({ ...s, drafts: { ...s.drafts, [postId]: '' }, posts: { ...s.posts, [postId]: { ...s.posts[postId], comments: [...s.posts[postId].comments, comment] } } }));
      sendComment(postId, cid);
      return cid;
    },
    retryComment: (postId: string, cid: string) => {
      const c = state.posts[postId].comments.find((x) => x.id === cid);
      if (!c) return;
      updateComment(postId, cid, { state: 'sending' });
      sendComment(postId, cid);
    },
    /** Take a failed comment back into the composer. */
    editComment: (postId: string, cid: string) => {
      const c = state.posts[postId].comments.find((x) => x.id === cid);
      if (!c) return;
      set((s) => ({ ...s, drafts: { ...s.drafts, [postId]: c.text }, posts: { ...s.posts, [postId]: { ...s.posts[postId], comments: s.posts[postId].comments.filter((x) => x.id !== cid) } } }));
    },
    say,
  };
}

export type FeedStore = ReturnType<typeof createFeedStore>;

/* Creator feed — "a riso printer's field notebook": paper, hairline rules, two spot inks (blue for text-safe
   accents, coral for fills and marks), registration marks as the only ornament, square sheets instead of cards. */
.root {
  --cf-blue: #2b4aa8;   /* ≥ 6.3:1 on bg, surface and surface-2 */
  --cf-coral: #d9483a;  /* fills and marks only (≥ 3.38:1) — never small text */
  --mk-accent: var(--cf-coral);
  /* One light, from the top left: every shadow falls down and slightly right. Two layers each — a tight contact
     shadow and a wide ambient one; lifting shrinks the first and grows the second, pressing does the opposite. */
  --cf-shadow: 38 30 20;
  --cf-sheet-rest: 0 1px 1px rgb(var(--cf-shadow) / 0.07), 1px 4px 10px -4px rgb(var(--cf-shadow) / 0.12);
  --cf-sheet-lift: 0 2px 2px rgb(var(--cf-shadow) / 0.05), 6px 22px 40px -14px rgb(var(--cf-shadow) / 0.32);
  --cf-key-rest: 0 1px 1px rgb(var(--cf-shadow) / 0.2), 1px 3px 7px -3px rgb(var(--cf-shadow) / 0.3);
  --cf-key-lift: 0 1px 1px rgb(var(--cf-shadow) / 0.1), 2px 8px 16px -6px rgb(var(--cf-shadow) / 0.4);
  --cf-key-down: 0 0 0 rgb(var(--cf-shadow) / 0), 0 0 1px rgb(var(--cf-shadow) / 0.35);
  position: relative;
  min-height: 100dvh;
  background: var(--mk-bg);
  color: var(--mk-ink);
  font-family: var(--mk-font-text);
}
:global([data-theme='dark']) .root { --cf-blue: #9db2ff; --cf-coral: #ff7a63; --cf-shadow: 0 0 0; }

.page { max-width: 1200px; margin-inline: auto; padding: 0 16px 56px; }
.muted { color: var(--mk-ink-muted); }

.sampleBar {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 12px;
  margin: 0; padding: 10px 0; border-bottom: 1px solid var(--mk-line);
  font-size: 0.8125rem; color: var(--mk-ink-muted);
}
.sampleBar > :first-child { color: var(--cf-blue); }

.layout { display: grid; gap: 32px; padding-top: 28px; }
@container (min-width: 62rem) {
  .layout { grid-template-columns: minmax(300px, 360px) minmax(0, 640px); justify-content: center; gap: 56px; align-items: start; }
}
.main { min-width: 0; }
@container (max-width: 61.99rem) { .main { max-width: 640px; width: 100%; margin-inline: auto; } .proof { max-width: 640px; width: 100%; margin-inline: auto; box-sizing: border-box; } }

/* ── Profile: a proof sheet ─────────────────────────────────────────────── */
.proof { position: relative; padding: 26px 22px 22px; background: var(--mk-surface); border: 1px solid var(--mk-line); box-shadow: var(--cf-sheet-rest); }
@container (min-width: 62rem) { .proof { position: sticky; top: 72px; } }
.reg { position: absolute; width: 22px; height: 22px; color: var(--cf-blue); }
.regTL { top: -11px; left: -11px; } .regTR { top: -11px; right: -11px; }
.regBL { bottom: -11px; left: -11px; } .regBR { bottom: -11px; right: -11px; }
.slugRow { display: flex; justify-content: space-between; align-items: center; gap: 12px; color: var(--mk-ink-muted); }
.inks { display: flex; gap: 3px; }
.inks i { display: block; width: 14px; height: 14px; background: var(--cf-blue); }
.inks i + i { background: var(--cf-coral); }
.nameRow { display: flex; align-items: flex-end; gap: 14px; margin-top: 22px; }
.avatar {
  flex: none; display: grid; place-items: center; width: 56px; height: 56px; border-radius: 50%;
  background: var(--mk-ink); color: var(--mk-bg);
  font-family: var(--mk-font-mono); font-size: 0.75rem; letter-spacing: 0.08em;
}
.name {
  position: relative; margin: 0;
  font-family: var(--mk-font-display); font-weight: 800;
  font-size: clamp(3rem, 2.3rem + 3.6cqi, 4.25rem); line-height: 0.86; letter-spacing: -0.035em;
  color: var(--cf-blue);
}
@container (min-width: 62rem) { .name { font-size: 4rem; } }
.nameInk { position: relative; }
/* The coral plate, printed a hair out of register. Decorative copy; multiply mixes the overlap to plum. It is a plate
   in the registration field (JS drives `transform`); the printed offset is `translate`, which snaps to zero when the
   card is hovered or holds focus. */
.nameCoral {
  position: absolute; inset: 0; color: var(--cf-coral); translate: 0.05em 0.03em; mix-blend-mode: multiply; pointer-events: none;
  transition: translate var(--cf-press-dur) var(--cf-press);
}
.proof:hover .nameCoral, .proof:focus-within .nameCoral { translate: 0 0; }
:global([data-theme='dark']) .nameCoral { mix-blend-mode: screen; }
.handle { margin: 16px 0 0; font-family: var(--mk-font-mono); font-size: 0.8125rem; }
.role { margin: 2px 0 0; font-size: 0.875rem; color: var(--mk-ink-muted); }
.bio { margin: 14px 0 0; max-width: 36ch; font-family: var(--mk-font-serif); font-size: 1.25rem; line-height: 1.28; text-wrap: pretty; }
.stats { display: flex; gap: 28px; margin: 18px 0 6px; padding-top: 14px; border-top: 1px solid var(--mk-line-strong); }
.stats div { display: flex; flex-direction: column-reverse; gap: 2px; }
.stats dt { font-family: var(--mk-font-mono); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--mk-ink-muted); }
.stats dd { margin: 0; font-family: var(--mk-font-display); font-weight: 700; font-size: 1.5rem; font-variant-numeric: tabular-nums; letter-spacing: -0.01em; }
.profileActions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 18px; }

.follow, .primaryBtn {
  min-height: 44px; padding: 0 22px; border: 1.5px solid var(--cf-blue); border-radius: var(--mk-radius-s);
  background: var(--cf-blue); color: var(--mk-bg); font: inherit; font-size: 0.9375rem; font-weight: 600;
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.2), var(--cf-key-rest);
}
.follow { min-width: 7.5rem; }
.follow[aria-pressed='true'] { background: var(--mk-surface); color: var(--cf-blue); box-shadow: inset 0 1px 2px rgb(var(--cf-shadow) / 0.18), var(--cf-key-down); }
.primaryBtn:disabled { background: var(--mk-surface-2); border-color: var(--mk-line); color: var(--mk-ink-muted); cursor: not-allowed; box-shadow: none; }
.ghostBtn {
  display: inline-flex; align-items: center; gap: 8px; min-height: 44px; padding: 0 16px;
  border: 1px solid var(--mk-line-strong); border-radius: var(--mk-radius-s); background: var(--mk-surface); color: inherit; font: inherit; font-size: 0.875rem; font-weight: 500;
  box-shadow: var(--cf-key-rest);
}

/* Press depth on every control: hover lifts a pixel (contact shadow softens, ambient grows), press drops the face
   below its rest and collapses the shadow in one frame, release springs back on the `press` spring. */
.follow, .primaryBtn, .ghostBtn, .iconBtn, .action, .morph, .switch, .textBtn, .tab {
  transition:
    transform var(--cf-press-dur) var(--cf-press), box-shadow var(--cf-press-dur) var(--cf-press),
    background-color var(--mk-duration-fast) var(--mk-ease-standard), color var(--mk-duration-fast) var(--mk-ease-standard),
    border-color var(--mk-duration-fast) var(--mk-ease-standard);
}
@media (hover: hover) {
  .follow:hover, .primaryBtn:hover:not(:disabled) { transform: translateY(-1px); box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.2), var(--cf-key-lift); }
  .follow[aria-pressed='true']:hover { transform: none; background: var(--mk-surface-2); box-shadow: inset 0 1px 2px rgb(var(--cf-shadow) / 0.18), var(--cf-key-down); }
  .ghostBtn:hover, .iconBtn:hover:not(:disabled) { transform: translateY(-1px); background: var(--mk-surface-2); box-shadow: var(--cf-key-lift); }
  .action:hover, .morph:hover { transform: translateY(-1px); background: var(--mk-surface-2); box-shadow: var(--cf-key-rest); }
}
.follow:active, .primaryBtn:active:not(:disabled), .ghostBtn:active, .iconBtn:active:not(:disabled) {
  transform: translateY(1px) scale(0.98); box-shadow: inset 0 1px 2px rgb(var(--cf-shadow) / 0.22), var(--cf-key-down);
  transition-duration: var(--mk-duration-instant); transition-timing-function: var(--mk-ease-standard);
}
.action:active, .morph:active, .textBtn:active, .tab:active {
  transform: translateY(1px) scale(0.95); box-shadow: inset 0 1px 2px rgb(var(--cf-shadow) / 0.18);
  transition-duration: var(--mk-duration-instant); transition-timing-function: var(--mk-ease-standard);
}
.ghostBtn svg, .action svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.inlineError { margin: 8px 16px 10px; padding: 8px 12px; border-left: 3px solid var(--mk-danger); background: var(--mk-surface-2); font-size: 0.875rem; line-height: 1.4; }
.proof .inlineError { margin: 12px 0 0; }
.textBtn { min-height: 24px; padding: 2px 4px; border: 0; border-radius: var(--mk-radius-s); background: none; color: var(--cf-blue); font: inherit; font-weight: 600; text-decoration: underline; text-underline-offset: 2px; }
@media (hover: hover) { .textBtn:hover { background: var(--mk-surface-2); } }

/* ── Settings + tabs ────────────────────────────────────────────────────── */
.settings { display: flex; flex-wrap: wrap; gap: 0 18px; margin-bottom: 8px; }
.switch { display: inline-flex; align-items: center; gap: 10px; min-height: 44px; padding: 0 2px; border: 0; background: none; color: inherit; font: inherit; font-size: 0.875rem; }
.switchTrack { position: relative; flex: none; width: 34px; height: 20px; border: 1.5px solid var(--mk-line-strong); border-radius: 999px; box-sizing: border-box; transition: background-color var(--mk-duration-fast) var(--mk-ease-standard); }
.switchThumb { position: absolute; top: 2.5px; left: 2.5px; width: 12px; height: 12px; border-radius: 50%; background: var(--mk-ink); box-shadow: 0 1px 1px rgb(var(--cf-shadow) / 0.3); transition: transform var(--cf-press-dur) var(--cf-press), scale var(--cf-press-dur) var(--cf-press); }
.switch:active .switchThumb { scale: 1.22 0.9; transition-duration: var(--mk-duration-instant); }
@media (hover: hover) { .switch:hover .switchTrack { border-color: var(--mk-ink); } }
.switch[aria-checked='true'] .switchTrack { background: var(--cf-blue); border-color: var(--cf-blue); }
.switch[aria-checked='true'] .switchThumb { transform: translateX(14px); background: var(--mk-bg); }
.switchNote { padding: 1px 6px; border: 1px solid var(--mk-line-strong); font-family: var(--mk-font-mono); font-size: 0.625rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--mk-ink-muted); }

.tabs { display: flex; gap: 6px; margin-bottom: 22px; border-bottom: 1px solid var(--mk-line-strong); }
.tab {
  display: inline-flex; align-items: center; gap: 8px; min-height: 44px; margin-bottom: -1px; padding: 0 12px;
  border: 0; border-bottom: 3px solid transparent; background: none; color: var(--mk-ink-muted); font: inherit; font-size: 0.9375rem; font-weight: 600;
}
@media (hover: hover) { .tab:hover { color: var(--mk-ink); background: color-mix(in oklab, var(--mk-surface-2) 60%, transparent); } }
.tab[aria-selected='true'] { color: var(--mk-ink); border-bottom-color: var(--cf-coral); }

/* ── Pinned (composed reaction-burst recipe) ────────────────────────────── */
.pinned { margin-bottom: 32px; }
.pinnedHead { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; padding-bottom: 8px; border-bottom: 1px solid var(--mk-line-strong); }
.pinnedHead h3 { margin: 0; color: var(--cf-blue); }
.pinnedStage { position: relative; background: var(--mk-surface); border: 1px solid var(--mk-line); border-top: 0; overflow: hidden; box-shadow: var(--cf-sheet-rest); }
/* The composed reaction-burst chips get the page's press depth (same light, same spring). */
.pinnedStage button[aria-pressed] {
  box-shadow: var(--cf-key-rest);
  transition:
    transform var(--cf-press-dur) var(--cf-press), box-shadow var(--cf-press-dur) var(--cf-press),
    background-color var(--mk-duration-fast) var(--mk-ease-standard), color var(--mk-duration-fast) var(--mk-ease-standard), border-color var(--mk-duration-fast) var(--mk-ease-standard);
}
@media (hover: hover) { .pinnedStage button[aria-pressed]:hover { transform: translateY(-1px); box-shadow: var(--cf-key-lift); } }
.pinnedStage button[aria-pressed]:active { transform: translateY(1px) scale(0.97); box-shadow: inset 0 1px 2px rgb(var(--cf-shadow) / 0.25), var(--cf-key-down); transition-duration: var(--mk-duration-instant); }
.pinnedStage button[aria-pressed='true'] { box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.12), var(--cf-key-rest); }
.pinnedNo {
  display: block; margin: 18px 18px -8px auto; width: max-content; pointer-events: none;
  font-family: var(--mk-font-display); font-weight: 800; font-size: clamp(5.5rem, 4rem + 6cqi, 7.5rem); line-height: 0.8; letter-spacing: -0.05em;
  color: transparent; -webkit-text-stroke: 1.5px var(--cf-blue);
}
@container (min-width: 62rem) { .pinnedNo { position: absolute; top: 0; right: 0; margin: 22px 26px 0 0; font-size: 7.5rem; } }

/* ── Feed ───────────────────────────────────────────────────────────────── */
.feedNote { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; margin: 0 0 14px; font-size: 0.8125rem; color: var(--mk-ink-muted); }
.feed { display: grid; gap: 28px; }
.post {
  position: relative; isolation: isolate; background: var(--mk-surface); border: 1px solid var(--mk-line); scroll-margin-top: 64px;
  box-shadow: var(--cf-sheet-rest);
  transition: transform var(--cf-settle-dur) var(--cf-settle);
}
/* The lifted shadow is its own layer whose opacity changes, so a lift never repaints a large shadow per frame. */
.post::before {
  content: ''; position: absolute; inset: -1px; z-index: -1; pointer-events: none;
  box-shadow: var(--cf-sheet-lift); opacity: 0; transition: opacity var(--cf-settle-dur) var(--cf-settle);
}
@media (hover: hover) {
  .post:hover { transform: translateY(-3px); }
  .post:hover::before { opacity: 1; }
}
.post:focus-visible { outline: 2px solid var(--mk-focus); outline-offset: 3px; }
.postHead { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 10px; padding: 12px 16px; }
.avatarSm { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; background: var(--mk-ink); color: var(--mk-bg); font-family: var(--mk-font-mono); font-size: 0.625rem; letter-spacing: 0.06em; }
.byline { display: grid; margin: 0; line-height: 1.3; }
.author { font-weight: 600; font-size: 0.9375rem; }
.meta { font-size: 0.8125rem; color: var(--mk-ink-muted); }
.slug { font-family: var(--mk-font-display); font-weight: 800; font-size: 1.375rem; letter-spacing: -0.01em; color: var(--cf-blue); }
.media { position: relative; margin: 0; aspect-ratio: 4 / 5; overflow: hidden; border-block: 1px solid var(--mk-line); touch-action: manipulation; user-select: none; -webkit-user-select: none; -webkit-touch-callout: none; cursor: default; }
.mediaArt { width: 100%; height: 100%; }
/* A print: paper + blue plate below, the coral plate above it (multiply), paper grain over both. */
.print { position: relative; width: 100%; height: 100%; overflow: hidden; isolation: isolate; }
.plate { position: absolute; inset: 0; display: block; width: 100%; height: 100%; }
.coralPlate { mix-blend-mode: multiply; will-change: transform; }
.print::after {
  content: ''; position: absolute; inset: 0; pointer-events: none;
  background-image: var(--cf-grain); background-size: 128px 128px; mix-blend-mode: multiply; opacity: 0.32;
}
.heartPop { position: absolute; top: 50%; left: 50%; width: 30%; opacity: 0; transform: translate(-50%, -50%); pointer-events: none; }
.heartPop svg { display: block; width: 100%; fill: var(--cf-coral); stroke: #f2ede2; stroke-width: 1.5; }
.postText { margin: 14px 16px 4px; font-family: var(--mk-font-serif); font-size: 1.25rem; line-height: 1.3; text-wrap: pretty; }
.postTextLarge { margin: 2px 16px 8px; font-family: var(--mk-font-serif); font-size: clamp(1.5rem, 1.25rem + 1cqi, 1.875rem); line-height: 1.2; letter-spacing: -0.005em; text-wrap: pretty; }

.actions { display: flex; align-items: center; gap: 2px; padding: 4px 8px 8px; }
.actionsGap { flex: 1; }
.action {
  position: relative; display: inline-flex; align-items: center; gap: 6px; min-width: 44px; min-height: 44px; padding: 0 10px; justify-content: center;
  border: 0; border-radius: var(--mk-radius-s); background: none; color: inherit; font: inherit; font-size: 0.875rem; font-weight: 500;
}
.action svg { width: 24px; height: 24px; }
.action:hover, .morph:hover { background: var(--mk-surface-2); }
.actionCount { font-variant-numeric: tabular-nums; }
/* Visually hidden on phones (the icon carries it), but always part of the button's name. */
.actionLabel { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
@container (min-width: 28rem) { .actionLabel { position: static; width: auto; height: auto; margin: 0; overflow: visible; clip: auto; white-space: normal; } }

/* Morph toggles (like-heart-morph technique) */
.morph {
  display: inline-flex; align-items: center; gap: 6px; min-height: 44px; min-width: 44px; padding: 0 10px 0 7px; justify-content: center;
  border: 0; border-radius: var(--mk-radius-s); background: none; color: inherit; font: inherit; font-size: 0.875rem; font-weight: 500;
}
.morphIcon { flex: none; overflow: visible; }
.morphIcon * { transform-box: view-box; transform-origin: 24px 24px; }
.morphOutline { fill: none; stroke: currentColor; stroke-width: 2.7; stroke-linejoin: round; }
.morphFill { fill: var(--cf-coral); opacity: 0; transform: scale(0); }
.morph[data-kind='save'] .morphFill { fill: var(--cf-blue); transform: scaleY(0); transform-origin: 24px 7.500px; }
.morph[aria-pressed='true'] .morphFill { opacity: 1; transform: none; }
.morph[data-kind='like'][aria-pressed='true'] .morphOutline { stroke: var(--cf-coral); }
.morph[data-kind='save'][aria-pressed='true'] .morphOutline { stroke: var(--cf-blue); }
.morphBurst circle { fill: none; stroke: var(--cf-coral); stroke-width: 2; opacity: 0; }
.morphBurst line { stroke: var(--cf-blue); stroke-width: 2.25; stroke-linecap: round; opacity: 0; }
.morph[data-kind='like'] .morphCaption { min-width: 4.4ch; text-align: left; }
.morphCount { display: inline-block; overflow: clip; color: var(--mk-ink-muted); font-variant-numeric: tabular-nums; }
.morphCount span { display: inline-block; }
@container (max-width: 27.99rem) { .morph[data-kind='save'] .morphCaption { display: none; } }

/* Carousel (three proofs): native scroll-snap for touch and trackpads, pointer throw for a mouse. */
.carousel { overflow: hidden; border-block: 1px solid var(--mk-line); }
.track {
  display: flex; aspect-ratio: 4 / 5; overflow-x: auto; overscroll-behavior-x: contain; scroll-snap-type: x mandatory; scrollbar-width: none;
  user-select: none; -webkit-user-select: none; background: var(--mk-surface-2);
}
@media (pointer: fine) { .track { cursor: grab; } }
.track[data-dragging] { cursor: grabbing; }
.track[data-dragging], .track[data-gliding] { scroll-snap-type: none; }
.track::-webkit-scrollbar { display: none; }
.track:focus-visible { outline: 2px solid var(--mk-focus); outline-offset: -2px; }
.slide { flex: 0 0 100%; height: 100%; scroll-snap-align: start; }
.carouselBar { display: grid; grid-template-columns: 44px 1fr 44px; align-items: center; gap: 8px; padding: 6px 8px; border-top: 1px solid var(--mk-line); }
.carouselMid { display: grid; justify-items: center; gap: 5px; }
.dots { display: flex; gap: 4px; }
.dots i { display: block; width: 16px; height: 4px; border-radius: 2px; background: var(--mk-line-strong); opacity: 0.22; transform: scaleX(0.4); transition: transform var(--cf-press-dur) var(--cf-press), opacity var(--mk-duration-fast) var(--mk-ease-standard), background-color var(--mk-duration-fast) var(--mk-ease-standard); }
.dots i[data-on] { opacity: 1; background: var(--cf-blue); transform: none; }
.carouselPos { margin: 0; text-align: center; font-size: 0.8125rem; }
.carouselNum { margin-right: 6px; font-family: var(--mk-font-mono); font-weight: 600; color: var(--cf-blue); }
.iconBtn {
  display: grid; place-items: center; width: 44px; height: 44px; padding: 0; flex: none;
  border: 1px solid var(--mk-line); border-radius: var(--mk-radius-s); background: var(--mk-surface); color: inherit;
  box-shadow: var(--cf-key-rest);
}
.iconBtn svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.iconBtn:disabled { color: var(--mk-ink-muted); border-color: transparent; cursor: default; box-shadow: none; background: transparent; }

/* ── End of feed ────────────────────────────────────────────────────────── */
.caughtUp { margin: 44px 0 0; padding: 30px 20px 34px; text-align: center; border-block: 1px solid var(--mk-line-strong); }
.caughtUp p { max-width: 42ch; margin: 0 auto; font-size: 0.9375rem; line-height: 1.5; color: var(--mk-ink-muted); text-wrap: pretty; }
.caughtMark { width: 60px; height: 60px; fill: none; stroke: var(--cf-blue); stroke-width: 1.5; }
.caughtMark .caughtTick { stroke: var(--cf-coral); stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; }
.caughtTitle { margin: 10px 0 8px; font-family: var(--mk-font-display); font-weight: 800; font-size: clamp(1.75rem, 1.4rem + 1.6cqi, 2.25rem); line-height: 1; letter-spacing: -0.03em; color: var(--cf-blue); text-wrap: balance; }

.suggested { margin-top: 36px; }
.suggestedHead { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: flex-start; gap: 10px 16px; padding-bottom: 12px; }
.suggestedHead h3 { margin: 0 0 4px; }
.suggestedHead p { margin: 0; max-width: 46ch; font-size: 0.875rem; line-height: 1.45; }
.essay { padding: 18px 16px 4px; background: var(--mk-surface); border: 1px solid var(--mk-line); box-shadow: var(--cf-sheet-rest); }
.essay > p { margin: 0; }
.essayTitle { margin: 10px 0 0; font-family: var(--mk-font-serif); font-size: clamp(1.875rem, 1.5rem + 1.6cqi, 2.5rem); font-weight: 400; line-height: 1.02; letter-spacing: -0.01em; text-wrap: balance; }
.essay .essayDek { margin: 10px 0 6px; max-width: 46ch; font-size: 0.9375rem; line-height: 1.45; color: var(--mk-ink-muted); }
.essay .actions { padding-inline: 0; border-top: 1px solid var(--mk-line); margin-top: 12px; }

.editions { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 20px 16px; margin: 0 0 16px; padding: 0; list-style: none; }
.edition { display: grid; align-content: start; gap: 2px; font-size: 0.8125rem; }
.edition p { margin: 0; }
.editionArt {
  position: relative; isolation: isolate; aspect-ratio: 4 / 5; margin-bottom: 8px; border: 1px solid var(--mk-line); box-shadow: var(--cf-sheet-rest);
  transition: transform var(--cf-settle-dur) var(--cf-settle);
}
.editionArt::before { content: ''; position: absolute; inset: -1px; z-index: -1; box-shadow: var(--cf-sheet-lift); opacity: 0; transition: opacity var(--cf-settle-dur) var(--cf-settle); }
@media (hover: hover) {
  .edition:hover .editionArt { transform: translateY(-4px) rotate(-0.4deg); }
  .edition:hover .editionArt::before { opacity: 1; }
}
.editionTitle { font-size: 0.9375rem; font-weight: 600; line-height: 1.3; }

.footer { margin-top: 44px; padding-top: 14px; border-top: 1px solid var(--mk-line); font-size: 0.8125rem; color: var(--mk-ink-muted); }
.footer p { margin: 0; }

/* ── Sheet (comments, share) ────────────────────────────────────────────── */
.sheetLayer { position: absolute; inset: 0; z-index: 40; display: flex; flex-direction: column; justify-content: flex-end; align-items: center; }
.sheetScrim { position: absolute; inset: 0; background: rgb(14 14 12 / 0.48); }
.sheetPanel {
  --sheet-axis: y;
  position: sticky; bottom: 0; z-index: 1; display: flex; flex-direction: column; box-sizing: border-box;
  width: min(100%, 600px); max-height: calc(100dvh - 44px - 24px);
  background: var(--mk-surface); border: 1px solid var(--mk-line-strong); border-bottom: 0;
  border-radius: var(--mk-radius-m) var(--mk-radius-m) 0 0;
  box-shadow: 0 -1px 2px rgb(0 0 0 / 0.08), 0 -18px 48px -8px rgb(0 0 0 / 0.28);
}
.sheetPanel:focus { outline: none; }
.sheetPanel:focus-visible { outline: 2px solid var(--mk-focus); outline-offset: -2px; }
@container (min-width: 62rem) {
  .sheetLayer { justify-content: flex-start; align-items: flex-end; }
  .sheetPanel { --sheet-axis: x; top: 44px; bottom: auto; width: 440px; height: calc(100dvh - 44px); max-height: none; border-bottom: 1px solid var(--mk-line-strong); border-right: 0; border-radius: var(--mk-radius-m) 0 0 var(--mk-radius-m); box-shadow: -1px 0 2px rgb(0 0 0 / 0.08), -18px 0 48px -8px rgb(0 0 0 / 0.28); }
}
/* The head is the drag handle (down on phones, right on the drawer); its controls stay plain buttons. */
.sheetHead { position: relative; display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; padding: 22px 16px 12px; border-bottom: 1px solid var(--mk-line); touch-action: none; cursor: grab; }
.sheetPanel[data-dragging] .sheetHead { cursor: grabbing; }
.grabber { position: absolute; top: 8px; left: 50%; width: 40px; height: 4px; margin-left: -20px; border-radius: 2px; background: var(--mk-line-strong); opacity: 0.3; transition: opacity var(--mk-duration-fast) var(--mk-ease-standard); }
.sheetHead:hover .grabber, .sheetPanel[data-dragging] .grabber { opacity: 0.6; }
@container (min-width: 62rem) {
  .sheetHead { padding-left: 22px; padding-top: 16px; }
  .grabber { top: 50%; left: 7px; width: 4px; height: 40px; margin: -20px 0 0; }
}
.sheetHead p { margin: 0; }
.sheetTitle { margin: 4px 0 0; font-family: var(--mk-font-display); font-size: 1.25rem; font-weight: 700; line-height: 1.15; letter-spacing: -0.01em; text-wrap: balance; }
.sheetBody { flex: 1 1 auto; min-height: 96px; overflow-y: auto; overscroll-behavior: contain; padding: 4px 16px 12px; }
.sheetFoot { padding: 12px 16px calc(14px + env(safe-area-inset-bottom, 0px)); border-top: 1px solid var(--mk-line); }

.comments { display: grid; margin: 0; padding: 0; list-style: none; }
.comment { display: grid; grid-template-columns: 32px 1fr; gap: 10px; padding: 12px 0; border-bottom: 1px solid var(--mk-line); overflow: hidden; }
.comment[data-state='sending'] .commentText { color: var(--mk-ink-muted); }
.comment .inlineError { margin: 6px 0 0; }
.avatarXs { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; background: var(--mk-surface-2); font-family: var(--mk-font-mono); font-size: 0.5625rem; letter-spacing: 0.04em; }
.commentBody { min-width: 0; }
.commentMeta { margin: 0; font-size: 0.8125rem; color: var(--mk-ink-muted); }
.commentMeta .author { color: var(--mk-ink); font-size: 0.875rem; }
.pending { color: var(--cf-blue); }
.commentText { margin: 2px 0 0; font-size: 0.9375rem; line-height: 1.45; overflow-wrap: anywhere; }
.empty { margin: 0; padding: 18px 0; color: var(--mk-ink-muted); }

.composer { display: grid; gap: 6px; }
.composerLabel { font-size: 0.875rem; font-weight: 600; }
.composer textarea {
  box-sizing: border-box; width: 100%; min-height: 64px; padding: 10px 12px; resize: vertical;
  border: 1px solid var(--mk-line-strong); border-radius: var(--mk-radius-s); background: var(--mk-bg); color: inherit; font: inherit; font-size: 1rem; line-height: 1.4;
}
.composerRow { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: flex-start; gap: 10px 14px; }
.hint { flex: 1 1 220px; margin: 0; font-size: 0.75rem; line-height: 1.45; color: var(--mk-ink-muted); }

.copy { display: grid; gap: 8px; padding: 12px 0 4px; }
.copy > p { margin: 0; }
.copyRow { display: flex; flex-wrap: wrap; gap: 8px; }
.copyInput { flex: 1 1 200px; min-width: 0; min-height: 44px; box-sizing: border-box; padding: 0 12px; border: 1px solid var(--mk-line-strong); border-radius: var(--mk-radius-s); background: var(--mk-bg); color: inherit; font-family: var(--mk-font-mono); font-size: 0.8125rem; }

/* Reduced motion: states still change (fill, shadow, colour) but nothing travels or springs. */
@media (prefers-reduced-motion: reduce) {
  .post, .post::before, .editionArt, .editionArt::before, .nameCoral, .switchThumb, .dots i,
  .follow, .primaryBtn, .ghostBtn, .iconBtn, .action, .morph, .switch, .textBtn, .tab, .pinnedStage button[aria-pressed] { transition: none; }
  .post:hover, .edition:hover .editionArt, .follow:hover, .primaryBtn:hover, .ghostBtn:hover, .iconBtn:hover, .action:hover, .morph:hover,
  .follow:active, .primaryBtn:active, .ghostBtn:active, .iconBtn:active, .action:active, .morph:active, .textBtn:active, .tab:active,
  .pinnedStage button[aria-pressed]:hover, .pinnedStage button[aria-pressed]:active { transform: none; }
  .coralPlate { will-change: auto; }
}
.root[data-reduced] .post, .root[data-reduced] .post::before, .root[data-reduced] .editionArt, .root[data-reduced] .nameCoral,
.root[data-reduced] .follow, .root[data-reduced] .primaryBtn, .root[data-reduced] .ghostBtn, .root[data-reduced] .iconBtn,
.root[data-reduced] .action, .root[data-reduced] .morph, .root[data-reduced] .switchThumb, .root[data-reduced] .dots i { transition: none; }
.root[data-reduced] .post:hover, .root[data-reduced] .edition:hover .editionArt, .root[data-reduced] :is(.follow, .primaryBtn, .ghostBtn, .iconBtn, .action, .morph, .textBtn, .tab):is(:hover, :active) { transform: none; }
